save(55,dict(paragraphs=["Elanaaga is a Telugu poet, translator and paediatrician whose work moves between Telugu and English. His writing includes metrical and experimental poetry as well as literary translation. He received the Sahitya Akademi Translation Prize for 2023 for Ghalib Naati Kaalam, his Telugu translation of Pavan K. Varma’s biography Ghalib: The Man, The Times.","In his Kabita Live poems, moral questions become vivid, sometimes unsettling images. ‘The Awaited Arrival’ addresses impartiality as an absent presence, while ‘Inner Embers’ measures war through the suffering of ordinary people. ‘Quagmire of Confusion’ turns inward, tracing the way anger and distorted perception can unsettle both thought and language."],sources=[source('Episteme, June 2017 — Closed Doors and Other Poems','https://episteme.net.in/content/73/3832/attachments/AmmangipoemTrnslation.pdf',['Translator biography: paediatrician, Telugu/English writer, metrical and experimental poetry, translation work.']),source('Sahitya Akademi — Translation Prize 2023','https://sahitya-akademi.gov.in/pdf/Pressrelease_TP-2023.pdf',['Telugu award selected Ghalib Naati Kaalam by Elanaaga (N. Surendra); original Pavan K. Varma biography in English, p25.'])],identity_match='Distinctive pen name and Telugu/English translation plus paediatrician career match captured biography. Official award record identifies pen name as Elanaaga (N. Surendra).',poems_read=[dict(id=53,title='The Awaited Arrival',basis='Full original read: impartiality and probity personified as banished figures.'),dict(id=349,title='Inner Embers',basis='Full original read: civilian suffering and destructive war imagery.'),dict(id=467,title='Quagmire of Confusion',basis='Full original read: tangled language, anger and rope/serpent misperception.')],limitations=['Dated book totals differ; omitted current count.','Award year2023 distinguished from presentation year2024.','Existing translations and translator credits unchanged; no claim that all archive poems were originally composed in English.','No independently verified book product URL added.'],next_action='Author/editor review, including preferred transliteration of award-winning title.'))
